import { useEffect } from "react";
import { useParams, useNavigate, Link, useLocation } from "react-router-dom";
import GameCard from "../components/GameCard";
import { useGames } from "../hooks/useGames";
import { CATEGORY_META } from "../utils/gameUtils";

function updateMetaTag(name, content, property = false) {
  if (!content) return;
  const selector = property ? `meta[property="${name}"]` : `meta[name="${name}"]`;
  let element = document.head.querySelector(selector);
  if (!element) {
    element = document.createElement("meta");
    if (property) {
      element.setAttribute("property", name);
    } else {
      element.setAttribute("name", name);
    }
    document.head.appendChild(element);
  }
  element.setAttribute("content", content);
}

export default function GamePage() {
  const { id } = useParams();
  const nav = useNavigate();
  const { games, loading } = useGames();
  const location = useLocation();

  if (loading) return <h2 className="loading-text">Loading Game...</h2>;

  const game = games.find((g) => g.slug === id || g._id === id || g.Name.toLowerCase().replace(/[^a-z0-9]+/g, "-") === id);

  useEffect(() => {
    if (!game) return;

    document.title = `${game.Name} • PokiPlay`;
    updateMetaTag("description", game.description);
    updateMetaTag("og:title", `${game.Name} • PokiPlay`, true);
    updateMetaTag("og:description", game.description, true);
    updateMetaTag("og:type", "website", true);
  }, [game]);

  useEffect(() => {
    if (location.hash === "#hero-overlay" && game) {
      setTimeout(() => {
        window.scrollTo({ top: 0, behavior: "smooth" });
      }, 150);
    }
  }, [location.hash, game]);

  if (!game) {
    return (
      <div className="not-found">
        <h2>Game Not Found</h2>
        <button className="btn-primary" onClick={() => nav("/")}>Back to Home</button>
      </div>
    );
  }

  const categoryMeta = CATEGORY_META[game.category] || CATEGORY_META.Other;
  const relatedList = games.filter(
    (other) =>
      other.category === game.category &&
      other.slug !== game.slug
  );

  return (
    <div className="modern-game-page">
      {/* HERO SECTION */}
      <div
        className="game-hero"
        style={{
          backgroundImage: `
          linear-gradient(
            rgba(0,0,0,0.45),
            rgba(0,0,0,0.55)
          ),
          url(${game.Icon})
        `
        }}
      >
        <div id="hero-overlay" className="hero-overlay">
          <img
            src={game.Icon}
            alt={game.Name}
            className="hero-game-image"
          />

          <h1 className="hero-game-title">
            {game.Name}
          </h1>

          <Link
            to={`/play/${game.slug}`}
            className="hero-play-btn"
          >
            ▶ Play Now
          </Link>
        </div>
      </div>

      {/* GAME DETAILS */}
      <section className="game-info-section">
        <div className="game-info-card">
          <h2>About this game</h2>

          <p>{game.description}</p>

          <h3>Instructions</h3>

          <p>{game.instructions}</p>

          <div className="game-links-row">
            <Link
              to="/search"
              className="btn-primary"
            >
              Browse More Games
            </Link>

            <button
              className="btn-back"
              onClick={() => nav(-1)}
            >
              Go Back
            </button>
          </div>
        </div>
      </section>

      {/* RELATED GAMES */}
      <section className="related-section">
        <div className="category-header">
          <div>
            <span
              className="category-label"
              style={{
                background: `${categoryMeta.color}22`,
                color: categoryMeta.color
              }}
            >
              {categoryMeta.icon} {game.category} Games
            </span>

            <span className="category-count">
              {
                games.filter(
                  (g) =>
                    g.category === game.category &&
                    g.slug !== game.slug
                ).length
              }{" "}
              games
            </span>
          </div>
        </div>

        <div className="grid related-games-grid">
          {relatedList.map((related) => (
            <Link key={related._id} to={`/game/${related.slug}#hero-overlay`} className="card-link">
              <div className="card">
                <div className="card-img-wrapper">
                  <div className="card-badges">
                    <span className="badge category-badge-card">{related.category}</span>
                    {related.isTrending && <span className="badge badge-trending">Trending</span>}
                    {related.isNew && <span className="badge badge-new">New</span>}
                  </div>
                  <img src={related.Icon} alt={related.Name} className="card-img" loading="lazy" />
                  <div className="play-overlay">
                    <button className="play-now-btn">
                      <span className="play-icon-small">▶</span> Play Now
                    </button>
                  </div>
                </div>
                <div className="card-body">
                  <p className="card-title">{related.Name}</p>
                </div>
              </div>
            </Link>
          ))}
        </div>
      </section>
    </div>
  );
}
